import{_ as t,a as i,b as l}from"./chunks/2ccf65e5016e018556ce.HPBCZwHr.js";import{_ as r,C as o,o as n,c as s,j as e,a as h,E as m,a6 as c}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"“深耕细分领域”是糟糕的建议（对聪明人来说）","description":"","frontmatter":{"title":"“深耕细分领域”是糟糕的建议（对聪明人来说）","originalTitle":"“Niche Down” Is Terrible Advice (For Smart People)","date":"2023-06-23","originalUrl":"https://thedankoe.com/letters/niche-down-is-terrible-advice-for-smart-people/","minutes":18,"sourceHash":"0f0190cd300475fce9126952d3e64896ead755471333055db49279bafbfe382c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/niche-down-is-terrible-advice-for-smart-people/"}]]},"headers":[],"relativePath":"letters/niche-down-is-terrible-advice-for-smart-people.md","filePath":"letters/niche-down-is-terrible-advice-for-smart-people.md"}'),d={name:"letters/niche-down-is-terrible-advice-for-smart-people.md"};function u(g,p,b,f,_,P){const a=o("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"深耕细分领域-是糟糕的建议-对聪明人来说",tabindex:"-1"},[h("“深耕细分领域”是糟糕的建议（对聪明人来说） "),e("a",{class:"header-anchor",href:"#深耕细分领域-是糟糕的建议-对聪明人来说","aria-label":'Permalink to "“深耕细分领域”是糟糕的建议（对聪明人来说）"'},"​")],-1)),m(a),p[1]||(p[1]=c('<p><strong>The Koe Letter</strong></p><p><em>2023年6月24日</em></p><p><strong>篇幅：</strong> 4000字</p><p><strong>阅读时间：</strong> 15分钟</p><hr><p>当我刚开始创业时，我完全不知道自己在干嘛。</p><p>我以为事情显而易见，尤其是在做自由职业时：</p><p>如果我有一项技能，而人们需要这项技能，他们就会雇佣我。</p><p>我忽视了一个事实：任何人都可以学会那项技能（而且在线自由职业领域已经开始充斥着像网页设计这样的单技能商品）。</p><p>这是我必须解决的第一个问题。</p><p>开门见山地说，我买了以下课程：</p><ul><li>自由职业</li><li>Facebook 广告</li><li>电商品牌建设</li><li>文案写作</li><li>销售与获客</li><li>至少15门虽然无关紧要但值得一提的网页开发课程</li></ul><p>当我尝试建立这些课程里所教的那种业务时，我并没有取得多大成功（这是我的问题，不是他们的）……</p><p>但我注意到了贯穿其中的一些规律。</p><p>有一个规律非常明显：</p><p>我必须非常明确我的目标受众是<em>谁</em>。</p><p><em>我必须深耕细分领域 (niche down)。</em></p><p>我得找出一个极度渴望的市场（比如健康）。</p><p>将其分解为子市场（比如健美）。</p><p>进一步缩小到细分市场（比如极简训练）。</p><p>研究该市场中的人群并收集他们的数据。这样，我就能直击他们的痛点，直接与他们对话。</p><p>这一切听起来太有道理了！</p><p>就是它了。</p><p>我知道我必须找到一个具体的人群，并以产品或服务的形式为他们量身定制我的技能。</p><p>这就是我一直缺失的秘密武器！</p><p>兄弟，深耕细分领域就行了！就这么简单！</p><p>这仍然是你在互联网圈子里能听到的最常见的建议。</p><p>但它也给新手带来了最多的困惑、不知所措和焦虑。</p><p>他们觉得如果一开始没有选对最赚钱的细分领域，就会注定失败。</p><p>所以他们把时间花在：</p><ul><li>在不同的细分领域之间反复横跳</li><li>为那个细分领域学习技能（这倒不是坏事）</li><li>最终没赚到钱，也没有积累到任何杠杆（这是坏事）</li></ul><p>我喜欢挑战普遍的观念（不仅限于商业），因为大多数时候它们被毫不怀疑地奉为圭臬。</p><p>这些观念能带来一些——但并非最好的——结果，所以人们蜂拥而至，躲在它们背后，并对任何说有更好方法的人大加挞伐。</p><p>商业教育很像政治或宗教，如果人们能意识到意识形态带来的危险，他们的日子会好过得多。</p><p>随着社交媒体的崛起，商业世界已经发生了翻天覆地的变化。</p><p>依赖冷拓客 (cold outbound outreach) 的商业模式，与建立一个能随着时间推移变暖并转化为客户的受众群体的商业模式之间，存在着巨大的差异。</p><p>你在网上学到的大多数东西都已经过时了，而且它们<em><strong>并不是</strong></em>新经济下做生意的最佳方式。</p><p>这封信会很长。</p><p>我们将深入探讨关于现实的形而上学解释。</p><p>这很重要，但如果你想直接跳到实操步骤，我们谈论的是：</p><ul><li>将你品牌的演进视为一个实现层级 (actualization hierarchy)（这样你就不必深耕细分领域）</li><li>如何从新手到高阶构建你品牌的每一个层级</li><li>在<em>每个层级要构建的</em>实际事物——这样你就知道现在该做什么</li></ul><p>在最后一节，<em>你就是无限的细分领域</em>。</p><h3 id="让你读到这封信的心态转变" tabindex="-1">让你读到这封信的心态转变 <a class="header-anchor" href="#让你读到这封信的心态转变" aria-label="Permalink to &quot;让你读到这封信的心态转变&quot;">​</a></h3><p>我不知道是怎么回事，也不知为何，我当时正在刷 Twitter。</p><p>我把它从手机上删了8年后，刚刚重新下载回来。</p><p>一条推文引起了我的注意。</p><p>是一个人既在卖网页设计服务，同时又在兜售自我提升的建议。</p><p>我曾被灌输了一种思想，即我必须通过冷呼叫 (cold call)、发冷邮件 (cold email) 和打广告，才能看到任何形式的商业成功。</p><p>经过多年的试错，我从未看到我想要的那种成功。我本可以死磕到底，但作为一个单打独斗的人，我永远也做不到。</p><p>当我看到人们通过发布内容（围绕着那些我知道自己也能谈论的话题）并以此获取客户时……我突然豁然开朗了。</p><p>使用冷邮件和私信 (DMs) 时：</p><ul><li>没人知道我是谁</li><li>没有任何前置信任</li><li>我从一开始就没有办法展示我的权威或成果——我必须证明自己</li><li>作为一个人，如果你想让每一条信息都个性化，那将是极大的手工工作量</li><li>我发出的每一次推销要么带来客户，要么石沉大海。在这个过程中，我没有建立任何杠杆。</li></ul><p>通过社交媒体内容、温和拓客 (warm outreach)（针对你的受众）以及推广：</p><ul><li>我随着时间的推移建立了声誉</li><li>我通过广度和深度建立信任（短内容和长内容）</li><li>我可以在不需要向受众解释我自己的情况下建立信任</li><li>我可以毫不费力地激发起人们对我产品的兴趣</li><li>没有任何东西会白费。所有的内容要么沉淀为数据（失败），要么转化为增长（成功）</li><li>随着我越做越大，我可以把品牌演变成我喜欢做的事情。随着时间的推移，我获得的是自由，而不是失去自由。</li></ul><p>于是，我开始在 Twitter 上写内容，为我的营销服务获取客户。</p><p><strong>另一个问题：</strong></p><p>人们觉得他们只能谈论一个与他们所卖东西相关的话题。</p><p>他们没有意识到：</p><ol><li><p>显然，你对自己售卖内容相关的话题很感兴趣。</p></li><li><p>你同时也关注了 200-500 个有着“完全不同”兴趣的其他博主。</p></li></ol><p>当<em>你都在关注那些谈论 10-20 种不同兴趣的人</em>时，你怎么会相信自己必须死守一个兴趣呢？</p><p>并不是人们对你的其他兴趣不感兴趣。</p><p>而是你不知道如何让你的兴趣对别人显得有趣。</p><p>人们觉得如果他们做得太宽泛，而不是垂直细分，他们就会稀释自己的价值，以至于赚不到一分钱。</p><p>我很早就认为这纯属扯淡。</p><p>每一个大型 YouTuber、播客主播或其他准名人，涉猎都非常宽泛。去看看 Iman Ghadzi 或 Hamza。</p><p>他们在社交媒体流量漏斗的顶层专注于初学者级别的教育。</p><p>他们在从低价到高价的产品和服务中专注于中高阶内容。</p><p>他们谈论的内容<em>在某种程度上</em>是具有整体性的。他们明白，谈论商业或自我提升，就势必要谈论健康和生活方式。</p><p>他们遥遥领先，因为他们懂人性。</p><p>可以这样想：</p><p>大多数<em>品牌</em>只是社交媒体世界中某个社区<em>里</em>的一栋建筑。</p><p>我希望我的品牌<em>本身就是</em>社交媒体世界中的一个社区。我的通讯 (newsletters)、引流诱饵 (lead magnets) 和产品就是其中的建筑，或者是数字房地产。</p><p>但是，很显然，你必须先盖好一栋楼，然后才能扩张。</p><p>人性是我们现在将要尝试打开的潘多拉魔盒。</p><h2 id="发展阶段、自然层级-以及它们如何在创作者经济中体现" tabindex="-1">发展阶段、自然层级，以及它们如何在创作者经济中体现 <a class="header-anchor" href="#发展阶段、自然层级-以及它们如何在创作者经济中体现" aria-label="Permalink to &quot;发展阶段、自然层级，以及它们如何在创作者经济中体现&quot;">​</a></h2><p>让我们从理解<em>层级 (hierarchies)</em> 和<em>发展阶段 (developmental stages)</em> 开始。</p><p><strong>层级是存在的基础。</strong></p><p>是的……即使是那些认为层级是坏东西的人，依然是在<em>把层级评级为坏</em>，而这本身就是一种层级。</p><p>现实的架构是由<em>心智单元 (units of mind)</em> 构成的。</p><p>这是一个在我的新书《专注的艺术 (The Art Of Focus)》（即将更新）中作为基础的概念。</p><p>其他人将这个词创造为“子整体 (holons)”，或者正如 Alan Watts 喜欢称之为“思想单元 (units of thought)”。</p><p>我更喜欢心智单元，因为唯心主义哲学 (mentalism) ——或者说万物皆心智。</p><p>在动物生命时期，或者在人类意识出现之前，没有心智去标记、解释和创造语言以便让所有人都能达成共识。</p><p>我们必须去理解现实。</p><p>这些心智“单元”就是一切。</p><p>你所能标记或感知的每一件事物。</p><p>它们有几个鲜明的特征：</p><p><strong>1) 心智单元具有层级性，并与世界的其余部分紧密相连。</strong></p><p>就像原子到细胞再到分子。</p><p>或者字母到句子到段落再到书籍。</p><p>或者内容到产品到品牌到社区再到社交媒体。</p><p>或者短内容到中篇内容再到长内容。</p><p>除此之外，这些单元中的任何一个都通过近端关系垂直或水平地与所有事物相连。</p><p>就像关于健美话题的短内容连接着健身房、你的营养、你的厨房、你手中的叉子，再到你肠道中的微生态系统。</p><p><strong>2) 心智单元是完整的部分。既是其自身的整体，也是更大事物的一部分。</strong></p><p>个人品牌的整体如果没有其各个组成部分就什么都不是，而大多数人忽略了为了演进而对每个部分的需求。</p><p><strong>统治者层级 (Dominator hierarchies)</strong> ——也就是那些让“层级”背负恶名并让人想要“推翻”父权制的层级——是指当层级中的某个单元试图占据统治地位时的情况。</p><p>就像癌细胞会在体内自我复制……直到它通过摧毁让整个层级赖以存在的较低层级，从而杀死宿主，或者说杀死层级。</p><p>癌细胞必须被治愈并重新融入层级，才能继续健康生长。</p><p><strong>3) 随之，心智单元出现、超越并包容。</strong></p><p>根据自然法则，能达到层级最高点的创作者少之又少。拥有百万粉丝的创作者数量注定是有限的。</p><p>但是，拥有十万粉丝的创作者数量——这足以赚到你无法想象的钱——却在日益增加。</p><p>随着创作者经济的不断演进，构成该经济层级的新层级将作为超越其组成部分的新整体而涌现。</p><p>我们还必须考虑到，你不需要有数字产品业务或粉丝量才能获得收入。</p><p>人们可以向你引荐项目，你可以创造实体产品，或者你可以获得巨大的机会。</p><p>但如果你想为自己创造这种可能性，其底层原则依然不变：品牌、内容、价值（或报价），以及营销（或推广）。</p><p>如果你不做贡献，你就无法从创作者经济中获得回报。</p><p>你是你网络这部分里的一个整体，你的网络是社区的一部分，社区是创作者经济的一部分，而创作者经济是互联网乃至更广阔世界的一部分。</p><p>如果你想生存，你就必须交换价值。</p><h3 id="理解你个人的演进" tabindex="-1">理解你个人的演进 <a class="header-anchor" href="#理解你个人的演进" aria-label="Permalink to &quot;理解你个人的演进&quot;">​</a></h3><p>任何事物都要经历发展阶段。</p><p>连你的个人品牌也不例外。</p><p>我在<a href="/letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake">一人企业路线图 (The One Person Business roadmap)</a> 中深入写过这个话题。</p><p>为了不把事情搞得太复杂，也不去写一本关于自我发展阶段和螺旋动力学 (spiral dynamics) 的书，让我们用两个例子来简化说明：</p><h3 id="_1-新手、中阶、高阶" tabindex="-1">1) 新手、中阶、高阶 <a class="header-anchor" href="#_1-新手、中阶、高阶" aria-label="Permalink to &quot;1) 新手、中阶、高阶&quot;">​</a></h3><p>在创作者之旅的每个阶段，你都必须优先考虑不同的事情。</p><p>新手不会有经过验证的想法。</p><p>他们也不会有成熟的品牌（或个人）哲学，因为你只能通过多年的写作和反思来找到它。</p><p>他们也没有必要的杠杆去专注于那些能带来指数级成果的东西（通讯、YouTube、数字产品等）。</p><p>关键是，你必须像其他人一样，把社交媒体作为一项技能来培养。你必须围绕你目前所处游戏级别的任何情况，来优先安排你的学习和行动。</p><h3 id="_2-前理性、理性与后理性-pre-rational-rational-post-rational" tabindex="-1">2) 前理性、理性与后理性 (Pre-rational, Rational, &amp; Post-Rational) <a class="header-anchor" href="#_2-前理性、理性与后理性-pre-rational-rational-post-rational" aria-label="Permalink to &quot;2) 前理性、理性与后理性 (Pre-rational, Rational, &amp; Post-Rational)&quot;">​</a></h3><p>这种发展进程最好地体现在那张臭名昭著的钟形曲线梗图上：</p><p><img src="'+t+'" alt=""></p><p>当人们开始在生活中的任何领域发展自己时，他们会紧抓相关意识形态的具体教义和原则。</p><p>如果他们不继续进化，他们就会被困在那个阶段。</p><p>就像有些信教的人变成了“狂热传教士”，机械地反刍他们学到的一切，而不加质疑或真正理解。</p><p>然后，他们到达了中级或理性的阶段。</p><p>在这里，人们开始质疑并反叛新手阶段。</p><p>在精神领域的发展中，这就是无神论者出现的地方。</p><p>在创作者领域的发展中，这是人们开始对这场游戏愤愤不平的地方（最近我在Twitter上经常看到这种现象。市场正在经历一个周期：人们互相曝光指责，抱怨游戏规则如何不公）。</p><p>“每个人都是抄袭狗。”</p><p>“教练把东西卖给教练就是在搞传销。”（缺乏对层级的理解）。</p><p>“高客单价销售是最好的商业模式，因为其他人都是平庸之辈，没我聪明。这也是我的生存之道，所以我必须与它深度绑定，否则我就会感到受到威胁”</p><p>同样，这可能会变得很危险。</p><p>最后，你进化到高级或后理性阶段。</p><p>在这个阶段，你重新发现这些原则，并能基于经验来审视它们。</p><p>就像大多数发展成熟的精神修行者会认同并践行《圣经》中的原则（以及所有信仰体系中指向真理的所有其他模式，因为他们不受文化认知的限制），但他们也明白，将其作为唯一的意识形态来布道是徒劳的（说什么否则你就会下地狱！）。</p><p>在创作者经济中，我们可以注意到几件事。</p><p>许多中阶者鄙视简单的陈词滥调或套话。他们进入了一个愤世嫉俗的阶段，试图反叛商业的本质。</p><p>（这并非坏事，但就像不断复制的癌细胞一样，你必须带着你的发现重新融入到层级中，才能晋升到下一个阶段——否则你就会像我反复看到的那样毁掉你的事业）。</p><p>高阶创作者将这些陈词滥调视为他们成长的支柱，但他们是从经验和权威的视角来看待的，否则那些简单的引语式内容就毫无影响力。</p><p>有了这么长的背景铺垫，我们现在可以从形而上的理解层面来谈谈“开创你的细分领域”。</p><h2 id="你就是无限的细分领域" tabindex="-1">你就是无限的细分领域 <a class="header-anchor" href="#你就是无限的细分领域" aria-label="Permalink to &quot;你就是无限的细分领域&quot;">​</a></h2><p>过去我已经多次讨论过“你就是最赚钱的细分领域”，<a href="/letters/the-most-profitable-niche-is-you-how-to-create-your-niche">特别是在这封信里。</a></p><p>为了不让这封信长达5000字（虽然还是有可能）：</p><ul><li>你的品牌愿景就是你对未来的愿景，这是你要引领追随者前往的方向。</li><li>你的品牌认同就是你的故事。你从哪里来，你如何蜕变。</li><li>你的内容通过教授你走到今天所学到的技能和兴趣来阐释这一点。</li><li>你的思想、观点和世界观是你以独特方式定位你内容的方法。</li><li>你的产品就是你为了帮助那些落后于你的人而创造的系统。</li></ul><p>让我们在这个想法的基础上更进一步。</p><p>希望下面这些能让你豁然开朗：</p><h3 id="别向下扎根细分领域——把你的品牌视为一个自我实现的层级" tabindex="-1">别向下扎根细分领域——把你的品牌视为一个自我实现的层级 <a class="header-anchor" href="#别向下扎根细分领域——把你的品牌视为一个自我实现的层级" aria-label="Permalink to &quot;别向下扎根细分领域——把你的品牌视为一个自我实现的层级&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>你是很复杂的。</p><p>好吧，至少这应该是你的目标。</p><p>宇宙朝着复杂性演进，随着你学习、实践和理解，你的自我意识也是如此。</p><p>你人格的复杂程度是由你所克服的目标或挑战决定的。</p><p>你实现的每一个目标都需要相匹配的技能水平和认知视角。</p><p>一旦你实现了那个目标，一条新的路径就会解锁，让你能朝着下一个目标努力。</p><p>你的技能水平（跨越多个领域）越高，你的自我复杂性就越高。</p><p>随着你复杂性的增加，你可以解决自己和他人生活中更深层、更有意义的问题。</p><p>如果你就是细分领域，那么随着你在追求目标的过程中技能和兴趣的进化，你的品牌也应该在复杂性上随之成长。</p><p>在你学习和掌握技能的同时，你的责任是去构建真实世界的项目，为他人带来成果。</p><p>这既是你在商业中创造盈利产品的方式，也是你履行精神责任的方式。</p><p>你达到的每一个发展层级，都要去构建一个有形的产品来反映它。这就是你教育追随者并建立权威的方式。</p><p>在我解决了我生活中的生产力问题之后，我做了一个能量手帐（Power Planner），现在它成了我的一个引流品。</p><p>在我在网页设计和自由职业上取得成果后，我为这两者分别制作了课程（这只会进一步加深我对这些事物的理解，教学正是你学习更多的方式）。</p><p>在我掌握了一套技能栈之后，我推出了一个品牌咨询服务，开始去帮助他人。</p><p>现在，许多人在细分向下扎根时错过的是这一点：</p><p>他们没有意识到，你创建的任何时事通讯、引流品、产品或服务，其本身<strong>就是</strong>一个受众群体。</p><p>你正在<strong>平台之外</strong>建立受众群体。</p><p>问题在于：</p><p>大多数人害怕去创造并发布任何东西。</p><p>他们没有意识到，长格式内容、产品和服务才是支撑你整个品牌的骨干。</p><p>我不想听起来显得自大，但下面这个例子能很好地说明问题。</p><p>“Dan，当我的推特客户数据全部跌至冰点时，你到底是怎么保持如此高的参与度的？”</p><p>唔，我倒想知道这是为什么……因为我不认为我的品牌是可以由别人代劳建立的。也不认为它是可以用模板化内容疯狂系统化糊弄过去的东西。</p><p>因为我在内容中深耕了深度，我有成千上万的学生，有几十万人阅读过我的时事通讯并下载了我的免费产品。</p><p>人们是基于了解我是谁以及我的哲学，才来阅读我的内容的。</p><p>这种话我已经说了好几年了，但大家只是粗略一瞥，因为做短格式内容和肤浅的产品才是捷径。</p><p>我的品牌是我毕生事业的载体。</p><p>我的品牌就是一个品牌，<strong>不是一个细分受众群体。</strong></p><p>它是社交媒体中的一座城市。一个由数以百万计的人组成的社区。</p><p>我的“能量手帐”拥有一个围绕生产力主题、达7万名下载者的细分受众群。这就是我占据的数字房地产。</p><p>我的时事通讯拥有一个围绕深度、哲学和商业主题、达12万名订阅者的细分受众群。</p><p>我的产品拥有一个围绕写作、品牌和商业主题、达15,000多名学生的细分受众群。</p><p>当你向下细分你的品牌时，我看到人们可能在3年后勉强达到总计10万的粉丝量。</p><p>我的“能量手帐”比那更算得上是一个细分受众群，而那里足足有7万人。</p><p>你明白我的意思了吗？</p><p>这就是你打破围绕你真实身份的边界，并（随着时间的推移）去构建任何你他妈想构建的东西的方式。</p><h3 id="每个人都从第一级开始" tabindex="-1">每个人都从第一级开始 <a class="header-anchor" href="#每个人都从第一级开始" aria-label="Permalink to &quot;每个人都从第一级开始&quot;">​</a></h3><p>当然，你不可能眨眼之间就把所有这些东西都建好。</p><p>我们在这里谈论的是发展的<strong>不同阶段</strong>。</p><p>你必须下定决心去建造你的金字塔的第一层。</p><p>一旦那个项目破土而出，就向下一个层级跨越，同时包容之前的层级。</p><p>大多数人永远无法进化，因为他们停止了构建。</p><p>因为停止了构建，所以他们停止了学习。</p><p>如果你没有把学到的东西应用到具体的事物上，你就没有在真正学习，到了那一步不过是精神自慰罢了。</p><p>教训：</p><p>如果你不在此品牌下构建数字房地产，你就会被困在那浅薄的发展水平上。</p><p>你将继续与处于那个层级的人竞争。</p><p>对大多数人来说，这意味着写内容、拿单子，然后陷入饱一顿饥一顿的服务型业务循环中无法自拔。</p><h3 id="建立权威与实现增长的聪明进阶之路" tabindex="-1">建立权威与实现增长的聪明进阶之路 <a class="header-anchor" href="#建立权威与实现增长的聪明进阶之路" aria-label="Permalink to &quot;建立权威与实现增长的聪明进阶之路&quot;">​</a></h3><p>以下是我为新手推荐的进阶路线。</p><p>如果我能回到过去优化我所构建的东西，我就会这么做。</p><p><strong>1) 确定通向你愿景的2-3个主题</strong></p><p><img src="'+l+'" alt=""></p><p>认清你在生活中想要什么，那就是你要带领追随者前进的方向。</p><p>你的技能和兴趣就是你以独特方式到达那里的途径。</p><p>就像想要获得自由的人，有的可以开启电商业务，有的可以实践预算技巧，还有的则可以通过副业成为数字游民。</p><p>我在<a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">如何撰写社交媒体内容这封信中</a>对此做了深入拆解。</p><p><strong>2) 练习漏斗顶部的写作与增长</strong></p><p>你的首要任务是在社交媒体上实现品牌的持续增长。</p><p>“最容易”做大的平台是Twitter、Instagram、LinkedIn和其他短格式内容平台。你对自己的增长有更大的控制权。</p><p>你需要建立一个基础受众群体，随着时间的推移，你可以用它来为你的数字房地产、产品和服务提供燃料。</p><p>随着你受众的增长，你构建并谈论任何你想谈论之物的杠杆力也随之增加。</p><ul><li>购买关于你所选主题的畅销书并如饥似渴地阅读它们。</li><li>关注谈论这些主题的社交媒体账号，从创作者（而不是消费者）的视角去模仿它们。</li><li>注意哪些写作风格、理念和结构表现得最好。</li></ul><p>这就是你练习写作的方式。</p><p>一开始你写的东西会很烂。</p><p>趁着还没人关注，赶紧把这个烂阶段熬过去。</p><p><strong>3) 创办一份时事通讯作为构建项目的容器</strong></p><p>我总是建议创办一份时事通讯。</p><p>你不<strong>一定</strong>要一开始就坚持规律地写。</p><p>你可以先建立订阅者基础，直到你准备好规律更新为止。</p><p>人们在建立时事通讯上拖延，因为这是一场长期游戏。你无法立即看到结果。</p><p>创办时事通讯的好处在于：</p><ul><li>你可以练习挖掘思想背后的深度。这会带来原创思考，并伴随写作的阵痛。你能更快地进步。</li><li>你可以把它作为一个阵地，用来撰写你的引流品或产品的模块或章节。不，哪怕你一开始免费发送出去也没关系。</li><li>作为新手，你展现出在平台之外提供价值的能力，这有助于提升人们眼中的权威感（“出售”某物对你的品牌有帮助，不出售某物反而会损害它）。</li></ul><p>无论你在接下来的步骤中创造什么，都可以用你的时事通讯来写出各个章节的第一版迭代。</p><p><strong>4) 创建一个引流品作为你的第一个“细分领域”</strong></p><p>我建立并测试过8-10个引流品。</p><p>从如何创建一个基础网站，到营销基础，再到“能量手帐”，再到我的创意生成系统。</p><p>拥有“细分”品牌的人必须坚持不懈地只谈论他们深扎的那个单一主题。</p><p>我们以视频剪辑为例（这也适用于其他每一个兴趣。健康、营养、营销技能、哲学，任何领域）。</p><p>如果我创建了一个关于视频剪辑基础的引流品，我是不是就得永远担心自己只能写这个？</p><p>还是说我想写什么就写什么，只需在里面插入我的引流品就行了？</p><p>特别是当我的引流品包含了我对该主题最好的思考和表述时。</p><p>并且，我还能一路构建我的时事通讯。</p><p>引流品创意的例子：</p><ul><li>获取结果的清单（比如网页设计清单）</li><li>用于系统的Notion模板（比如写作或习惯养成）</li><li>新手级电子书，涵盖基础知识，让人们能跟上你谈论的更高级的内容。</li><li>同样是新手基础知识的视频教程或屏幕录像。</li></ul><p>创建一个引流诱饵（lead magnet），在你想要变现——或者至少你认为自己想要变现——的主题上建立权威。你随时可以再创建另一个。</p><p>随着时间的推移，你将建立起一个由下载者组成的细分领域受众群体。</p><p><strong>5) 销售一个</strong> <strong>最小</strong> <strong>可行服务方案以获取经验</strong></p><p>你需要为引流诱饵的下载者提供一个“下一步”。</p><p>最好是某个你能变现的东西。</p><p>对于初学者，我推荐最小可行方案（minimum viable offer）。</p><p>这意味着一项单技能的自由职业服务（比如网页设计）或一项单兴趣的教练服务（比如生产力或健康）。</p><p>我以前讨论过这个，<a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">在一封专门的信件中（最佳在线商业模式）。</a></p><p>收费500到1000美元，直到你弄明白什么能带来真正的结果。</p><p>将其系统化。</p><p>提高收费。</p><p>用每个月3-4个客户来替代你的收入，并全职投入。</p><p><strong>6) 去细分化，进化，超越，包容</strong></p><p>到了这一步，你已经在一个细分领域建立了权威。</p><p>你应该花些时间在这个领域获取结果，同时在你的内容中测试不同的兴趣。</p><p>为了深化你的权威，并腾出空间探索新兴趣，你应该完成你的品牌自我实现金字塔。</p><ul><li>将你的自由职业或咨询服务转变为同期群课程（cohort-based course）。在这个层面上获取结果。</li><li>将该同期群课程产品化为数字产品。在这个层面上获取结果。</li><li>重复引流诱饵、服务、群组和产品的过程，直到你拥有内容、产品和服务的全面综合体。</li></ul><p>如果你想谈论某些兴趣，你需要有基础内容（比如引流诱饵或新闻通讯）就位，让人们能跟上你的节奏。</p><p>如果你在谈论一个新兴趣时没有获得互动，那是因为你还没有在其之下建立深度。</p><p>你需要让你的受众在理解上达到同一个频道。</p><h3 id="技能与兴趣的全面综合" tabindex="-1">技能与兴趣的全面综合 <a class="header-anchor" href="#技能与兴趣的全面综合" aria-label="Permalink to &quot;技能与兴趣的全面综合&quot;">​</a></h3><p>随着时间和精力的投入，比如说1到2年，你就可以真正开始做任何你想做的事了。</p><p>世界需要更多具有整体思维的综合者，因为现实并不像当前的学校系统那样被划分成一个个隔间。</p><p>你可能现在还看不到，但你正在创造社会。</p><p>你的工作是去注意兴趣与行业之间的规律模式。</p><p>在你的创作中将它们连接起来。</p><p>成为一个现代博学家。</p><p>一个数字时代的文艺复兴式全才。</p><p>通过你的兴趣探索现实。</p><p>通过内容分发你的发现。</p><p>通过创造值得收费的东西，靠做自己热爱的事谋生。</p><p>顺应宇宙的方向，沐浴在随之而来的喜悦之中。</p><p>并且，好好享受你周末剩下的时光。</p><p>– 丹·柯伊 (Dan Koe)</p><hr><p><a href="/en/letters/niche-down-is-terrible-advice-for-smart-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',272))])}const T=r(d,[["render",u]]);export{w as __pageData,T as default};
